const fs = require('fs');
const https = require('https');

// Configuration
const API_URL = 'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts';
const API_KEY = process.env.CROSSMINT_API_KEY;
const RECIPIENTS_FILE = '/home/user/recipients.json';
const SUMMARY_FILE = '/home/user/airdrop_summary.json';

// NFT Metadata
const NFT_METADATA = {
  name: 'Welcome NFT',
  description: 'Airdrop token',
  image: 'https://example.com/welcome.png'
};

// Function to make HTTP request
function makeRequest(url, options, data) {
  return new Promise((resolve, reject) => {
    const req = https.request(url, options, (res) => {
      let body = '';
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          body: body
        });
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    if (data) {
      req.write(JSON.stringify(data));
    }
    req.end();
  });
}

// Main function
async function main() {
  try {
    // Read recipients from JSON file
    const recipientsData = fs.readFileSync(RECIPIENTS_FILE, 'utf8');
    const recipients = JSON.parse(recipientsData);

    if (!Array.isArray(recipients)) {
      throw new Error('recipients.json must contain an array of email addresses');
    }

    console.log(`Processing ${recipients.length} recipients...`);

    const results = [];

    // Process each recipient
    for (const email of recipients) {
      const recipient = `email:${email}:polygon-amoy`;
      console.log(`Minting to ${email}...`);

      const requestBody = {
        recipient: recipient,
        metadata: NFT_METADATA
      };

      try {
        const response = await makeRequest(API_URL, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-api-key': API_KEY
          }
        }, requestBody);

        const status = (response.statusCode === 200 || response.statusCode === 202) ? 'sent' : 'error';

        results.push({
          email: email,
          status: status,
          response: response.body
        });

        console.log(`  Status: ${status} (${response.statusCode})`);
      } catch (error) {
        results.push({
          email: email,
          status: 'error',
          response: error.message
        });
        console.log(`  Error: ${error.message}`);
      }
    }

    // Write summary
    const summary = {
      total: recipients.length,
      results: results
    };

    fs.writeFileSync(SUMMARY_FILE, JSON.stringify(summary, null, 2));
    console.log(`\nSummary written to ${SUMMARY_FILE}`);
    console.log(`Total processed: ${summary.total}`);
    console.log(`Sent successfully: ${results.filter(r => r.status === 'sent').length}`);
    console.log(`Errors: ${results.filter(r => r.status === 'error').length}`);

  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

main();

